import{_ as e,o,c as a,ag as r}from"./chunks/framework.DyZQ0-wY.js";const s="/footnotes/guide/assets/practice.DJfAInG6.png",u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"footnotes/index.md","filePath":"footnotes/index.md"}'),n={name:"footnotes/index.md"};function i(h,t,l,d,c,g){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Footnotes helps you learn how to dance a StepMania chart. A dancing bot stands on a dance pad at the top of the screen and steps exactly when you should, right above the arrows you&#39;re about to hit. Copy its feet while you read the arrows, and slow the song down until the pattern feels natural.</p><p><img src="'+s+'" alt="The Footnotes practice screen"></p><h2 id="your-first-song" tabindex="-1">Your first song <a class="header-anchor" href="#your-first-song" aria-label="Permalink to &quot;Your first song&quot;">​</a></h2><ol><li>Open <a href="https://chihduo.github.io/footnotes/" target="_blank" rel="noreferrer">Footnotes</a> and press <strong>Try the demo song</strong>.</li><li>Pick a chart. <strong>Beginner</strong> is a good place to start.</li><li>Press <kbd>Space</kbd> or the play button to start the song, and watch the bot.</li></ol><p>To practice your own songs, see <a href="./loading-songs.html">Loading songs</a>.</p><h2 id="reading-the-bot" tabindex="-1">Reading the bot <a class="header-anchor" href="#reading-the-bot" aria-label="Permalink to &quot;Reading the bot&quot;">​</a></h2><ul><li>The pad at the top is the dance stage, seen from above. Blue is your <strong>left</strong> foot and orange is your <strong>right</strong> foot, and each foot is labeled <strong>L</strong> or <strong>R</strong>.</li><li>A foot moves onto a panel just as the arrow for that panel reaches the targets. The panel lights up when it&#39;s stepped on.</li><li>A foot that holds a panel for a hold note stays on it until the hold ends.</li><li>When the chart asks you to cross over or turn, the bot&#39;s feet cross and turn too.</li></ul><p>The bot&#39;s footing comes from SMEditor&#39;s <a href="./../parity.html">parity checker</a>, which works out the most natural foot for every arrow. It&#39;s right for most charts, but it&#39;s a prediction, so trust your body when a step feels wrong.</p><h2 id="the-practice-screen" tabindex="-1">The practice screen <a class="header-anchor" href="#the-practice-screen" aria-label="Permalink to &quot;The practice screen&quot;">​</a></h2><ol><li><strong>Top bar:</strong> playback rate, the assist tick and metronome, and scroll speed.</li><li><strong>Dancing bot:</strong> the pad with the two feet.</li><li><strong>Targets:</strong> arrows rise into these, just under the bot. Once an arrow passes the targets, it slides away under the pad.</li><li><strong>Note layout:</strong> the strip on the right shows the whole chart. Click or drag on it to jump to any part of the song.</li><li><strong>Bottom bar:</strong> skip to the start or end, play or pause, the current time and beat, <strong>Charts</strong> to switch difficulty, and <strong>Exit practice</strong>.</li></ol><p>See <a href="./controls.html">Controls</a> for all the buttons and keys.</p><h2 id="leaving-practice-mode" tabindex="-1">Leaving practice mode <a class="header-anchor" href="#leaving-practice-mode" aria-label="Permalink to &quot;Leaving practice mode&quot;">​</a></h2><p>Press <strong>Exit practice</strong> or <kbd>Shift</kbd>+<kbd>H</kbd> to switch to the full SMEditor chart editor, with all of its menus and tools. Press <kbd>Shift</kbd>+<kbd>H</kbd> again, or choose <strong>View &gt; Dance practice mode</strong>, to come back.</p>',14)])])}const f=e(n,[["render",i]]);export{u as __pageData,f as default};
